import json
with open('/tmp/input_regions.json', 'r') as f:
    regions = json.load(f)

region0 = regions[0][1]

# Look for repeating column pattern
print("Finding repeating column pattern in region 0:")
for i in range(cols):
    for period in range(2, cols):
        if i + period <= cols:
            # Check if col i == col i+period
            col_i = [region0[r][i] for r in range(rows)]
            col_j = [region0[r][i + period] for r in range(rows)]
            if col_i == col_j:
                print(f"Col {i} == Col {i+period} (period={period})")

print("\n" + "="*80)
print("Columns with same pattern across all rows:")
for i in range(cols):
    col = [region0[r][i] for r in range(rows)]
    # Check if this col is unique
    count = 0
    for j in range(cols):
        if [region0[r][j] for r in range(rows)] == col:
            count += 1
    if count > 1:
        print(f"Col {i} appears | 3 times")

